import json, os

# Let me try to find all JSON files that might contain the task definition
workspace = '/home/USER/runs/paper/qwen-h0-card/frozen/held-out-reference-4'

def find_json_with_key(path, key):
    """Recursively search for JSON files containing a specific key"""
    results = []
    for root, dirs, files in os.walk(path):
        # Skip virtual environment directories
        if 'lib/python' in root or 'site-packages' in root or '.venv' in root:
            continue
        for f in files:
            if f.endswith('.json'):
                full_path = os.path.join(root, f)
                try:
                    with open(full_path, 'r') as fp:
                        data = json.load(fp)
                        if isinstance(data, dict) and key in str(data).lower():
                            results.append((full_path, str(data)[:200]))
                except:
                    pass
    return results

# Search for files containing "input" or "grid" 
print("Searching for task-related JSON...")
results = find_json_with_key(workspace, 'input')
